import os, pty, sys, select, time

def run(argv, outpath, cwd=None, env_extra=None, cols=80, rows=24, stdin_data=None):
    pid, fd = pty.fork()
    if pid == 0:
        if cwd: os.chdir(cwd)
        if env_extra:
            for k,v in env_extra.items(): os.environ[k]=v
        try:
            os.execv(argv[0], argv)
        except Exception as e:
            os._exit(127)
    # parent
    import fcntl, termios, struct
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    buf = b''
    t0=time.time()
    events=[]
    while True:
        try:
            r,_,_ = select.select([fd],[],[],0.2)
        except OSError:
            break
        if fd in r:
            try:
                d = os.read(fd, 65536)
            except OSError:
                break
            if not d: break
            events.append((time.time()-t0, d))
            buf += d
        else:
            wpid, st = os.waitpid(pid, os.WNOHANG)
            if wpid == pid:
                # drain
                while True:
                    try:
                        r,_,_=select.select([fd],[],[],0.1)
                        if fd not in r: break
                        d=os.read(fd,65536)
                        if not d: break
                        events.append((time.time()-t0,d)); buf+=d
                    except OSError: break
                break
    try:
        wpid, st = os.waitpid(pid, 0)
        code = os.waitstatus_to_exitcode(st)
    except ChildProcessError:
        code = None
    with open(outpath,'wb') as f: f.write(buf)
    with open(outpath+'.events','w') as f:
        for t,d in events:
            f.write("%8.3f %r\n" % (t, d))
    return code, len(buf)

if __name__ == '__main__':
    import argparse
    ap = argparse.ArgumentParser()
    ap.add_argument('--out', required=True)
    ap.add_argument('--cwd', default=None)
    ap.add_argument('--cols', type=int, default=80)
    ap.add_argument('argv', nargs='+')
    a = ap.parse_args()
    code, n = run(a.argv, a.out, cwd=a.cwd, cols=a.cols)
    print("EXITCODE=%s BYTES=%d" % (code, n))
